                        stack.pop()
                prev_bound[i] = stack[-1] if stack else -1
                stack.append(i)

            stack = []
            for i in range(n - 1, -1, -1):
                if is_max:
                    while stack and nums[stack[-1]] <= nums[i]:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] >= nums[i]:
                        stack.pop()
                next_bound[i] = stack[-1] if stack else n
                stack.append(i)

