#include <vector>
#include <algorithm>

class Solution {
public:
    long long minMaxSubarraySum(std::vector<int>& nums, int k) {
        int n = nums.size();

        auto compute = [&](bool is_max) -> long long {
            std::vector<int> prev_bound(n, -1);
            std::vector<int> next_bound(n, n);
            std::vector<int> stack;

            for (int i = 0; i < n; ++i) {
                if (is_max) {
                    while (!stack.empty() && nums[stack.back()] < nums[i]) stack.pop_back();
                } else {
                    while (!stack.empty() && nums[stack.back()] > nums[i]) stack.pop_back();
                }
                prev_bound[i] = stack.empty() ? -1 : stack.back();
                stack.push_back(i);
            }

            stack.clear();
            for (int i = n - 1; i >= 0; --i) {
                if (is_max) {
                    while (!stack.empty() && nums[stack.back()] <= nums[i]) stack.pop_back();
                } else {
                    while (!stack.empty() && nums[stack.back()] >= nums[i]) stack.pop_back();
                }
                next_bound[i] = stack.empty() ? n : stack.back();
                stack.push_back(i);
            }

            long long total = 0;
            for (int i = 0; i < n; ++i) {
                long long l = std::min(i - prev_bound[i], k);
                long long r = std::min(next_bound[i] - i, k);
                long long extra = std::max(0LL, l + r - 1 - k);
                long long count = l * r - (extra * (extra + 1)) / 2;
                total += 1LL * nums[i] * count;
            }
            return total;
        };

        return compute(true) + compute(false);
    }
};

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public long minMaxSubarraySum(int[] nums, int k) {
        return compute(nums, k, true) + compute(nums, k, false);
    }

    private long compute(int[] nums, int k, boolean isMax) {
        int n = nums.length;
        int[] prevBound = new int[n];
        int[] nextBound = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            if (isMax) {
                while (!stack.isEmpty() && nums[stack.peek()] < nums[i]) stack.pop();
            } else {
                while (!stack.isEmpty() && nums[stack.peek()] > nums[i]) stack.pop();
            }
            prevBound[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            if (isMax) {
                while (!stack.isEmpty() && nums[stack.peek()] <= nums[i]) stack.pop();
            } else {
                while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) stack.pop();
            }
            nextBound[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        long total = 0;
        for (int i = 0; i < n; i++) {
            long l = Math.min(i - prevBound[i], k);
            long r = Math.min(nextBound[i] - i, k);
            long extra = Math.max(0, l + r - 1 - k);
            long count = l * r - (extra * (extra + 1)) / 2;
            total += (long)nums[i] * count;
        }
        return total;
    }
}

